def biseccion(f, a, b, tol=1e-8, max_iter=100):
    if f(a) * f(b) >= 0:
        print("Bolzano no se cumple")
        return None, 0
    for k in range(max_iter):
        c = (a + b) / 2
        if abs(f(c)) < tol or (b - a) / 2 < tol:
            return c, k
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    return c, max_iter

