def determinante(m):
    n = len(m)
    # Copia para no modificar el original
    a = [fila[:] for fila in m]
    det = 1.0

    for i in range(n):
        # Pivoteo
        pivote = a[i][i]
        if pivote == 0:
            for j in range(i + 1, n):
                if a[j][i] != 0:
                    a[i], a[j] = a[j], a[i]
                    det = -det
                    pivote = a[i][i]
                    break
            else:
                return 0

        det *= pivote
        for j in range(i + 1, n):
            factor = a[j][i] / pivote
            for k in range(i, n):
                a[j][k] -= a[i][k] * factor

    return det

