def inversa(m):
    n = len(m)
    # Matriz aumentada [A | I]
    a = [fila[:] + [1 if i == j else 0 for j in range(n)] for i, fila in enumerate(m)]

    for i in range(n):
        # Pivoteo
        pivote = a[i][i]
        if pivote == 0:
            for j in range(i + 1, n):
                if a[j][i] != 0:
                    a[i], a[j] = a[j], a[i]
                    pivote = a[i][i]
                    break

        # Normalizar
        for k in range(2 * n):
            a[i][k] /= pivote

        # Eliminar
        for j in range(n):
            if j != i:
                factor = a[j][i]
                for k in range(2 * n):
                    a[j][k] -= a[i][k] * factor

    return [fila[n:] for fila in a]

