def lagrange(xs, ys, x):
    total = 0
    n = len(xs)
    for i in range(n):
        termino = ys[i]
        for j in range(n):
            if i != j:
                termino *= (x - xs[j]) / (xs[i] - xs[j])
        total += termino
    return total

