def diferencias_divididas(xs, ys):
    n = len(xs)
    coef = ys[:]
    for j in range(1, n):
        for i in range(n - 1, j - 1, -1):
            coef[i] = (coef[i] - coef[i - 1]) / (xs[i] - xs[i - j])
    return coef

def evaluar_newton(xs, coef, x):
    n = len(xs)
    resultado = coef[n - 1]
    for i in range(n - 2, -1, -1):
        resultado = resultado * (x - xs[i]) + coef[i]
    return resultado

