def metodo_hibrido(f, df, a, b, tol=1e-10, n_biseccion=5, max_iter=50):
    # Bisección para acercarse
    for _ in range(n_biseccion):
        c = (a + b) / 2
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c

    # Newton desde el punto medio
    x = (a + b) / 2
    for k in range(max_iter):
        dfx = df(x)
        if abs(dfx) < 1e-14:
            break
        x_nuevo = x - f(x) / dfx
        if abs(x_nuevo - x) < tol:
            return x_nuevo, n_biseccion + k
        x = x_nuevo
    return x, max_iter

